// ── Email sorter — deterministic pre-classification ──
// Decide everything rules CAN decide, so the LLM only sees genuinely ambiguous mail.

const TEAM = new Set([
  "user@example.com",
  "user@example.com",
  "user@example.com",
  "user@example.com",
]);
// Website form fill-outs — a SEPARATE workflow already replies to these. Don't touch.
const FORM_SENDERS = new Set(["user@example.com"]);

function extractEmail(f){
  if(!f) return "";
  if(typeof f==="object"){
    if(Array.isArray(f.value)&&f.value[0]&&f.value[0].address) return String(f.value[0].address).toLowerCase();
    if(f.address) return String(f.address).toLowerCase();
    if(f.text) f=f.text;
  }
  const s=String(f);
  const m=s.match(/[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/i);
  return (m?m[0]:s).trim().toLowerCase();
}
function extractName(f){
  if(!f) return "";
  if(typeof f==="object"){
    if(Array.isArray(f.value)&&f.value[0]&&f.value[0].name) return String(f.value[0].name).trim();
    if(f.text) f=f.text;
  }
  const m=String(f).match(/^\s*"?([^"<]+?)"?\s*</);
  return (m?m[1]:"").trim();
}
function getHeader(j,name){
  const n=name.toLowerCase();
  const h=j.headers||{};
  for(const k in h){ if(String(k).toLowerCase()===n) return String(h[k]); }
  if(Array.isArray(j.headerLines)){
    for(const line of j.headerLines){
      if(line && String(line.key||"").toLowerCase()===n) return String(line.line||"");
    }
  }
  return "";
}

const LLM_SYSTEM = [
"You are an email triage engine for our company. Team mail, website form submissions,",
"calendar/scheduling mail, verification codes, and obvious bulk/marketing mail have",
"ALREADY been filtered out before you see this. Your ONLY job: decide, using ONLY the",
"text explicitly in the email, whether it is LEAD, TRASH, or REVIEW.",
"",
"LEAD   - a real person having (or opening) a genuine business conversation with",
"         our company about our product/service: a prospective or existing customer, a",
"         reply in an ongoing sales/support thread, a real inbound question about what",
"         we do, pricing, a demo, a quote, next steps, a proposal. Test: a human wrote",
"         this TO US, ABOUT OUR business, expecting a real reply from a person.",
"TRASH  - anything else: cold outreach or pitches aimed AT us, vendor/agency/SEO/",
"         recruiting solicitation, promotions, product-update blasts, app/social",
"         notifications, receipts unrelated to a live deal, crypto/spam. Sign: THEY are",
"         selling to US, or no human reply is expected.",
"REVIEW - use ONLY when you truly cannot tell LEAD from TRASH from the text given. When",
"         unsure, choose REVIEW instead of guessing. REVIEW is never deleted.",
"",
"Rules:",
"- Judge from quoted evidence only; never assume unstated prior context.",
"- 'Re:' / 'Fwd:' alone does NOT make something a LEAD.",
"- Someone selling something to our company is TRASH even if personalized to us.",
"",
"Examples:",
"- 'Saw your site - can you send pricing for 25 users and availability for a demo next",
"  week?' -> LEAD (inbound buyer intent).",
"- 'Following up on the proposal you sent - the team approved, what are next steps?'",
"  -> LEAD (ongoing deal).",
"- 'I help SaaS companies book 30 meetings/month. Open to a quick call?' -> TRASH",
"  (they are selling to us).",
"- 'Your AWS invoice for June is ready.' -> TRASH (transactional, no reply expected).",
"- 'Quick question about what you guys do' from an unknown personal address, nothing",
"  else -> REVIEW (ambiguous).",
"",
"Output ONLY this JSON (no prose, no markdown fences):",
'{"evidence":"<exact quote(s) from the email, or empty>","category":"LEAD|TRASH|REVIEW","summary":"<one factual sentence stating only what the email says>"}'
].join("\n");

const out=[];
const items=$input.all();
for(let i=0;i<items.length;i++){
  const j=items[i].json;

  const from_email = extractEmail(j.from);
  const from_name  = extractName(j.from) || String(j.fromName ?? "");
  const subject    = String(j.subject ?? "").trim();
  const bodyFull   = String(j.text ?? j.textPlain ?? j.snippet ?? "").trim();
  const body       = bodyFull.slice(0,4000);
  const id         = String(j.id ?? j.messageId ?? "");
  const threadId   = String(j.threadId ?? "");
  const received_ms= j.internalDate ? String(j.internalDate)
                    : (j.date ? String(new Date(j.date).getTime()) : "");
  const domain     = from_email.split("@")[1] || "";
  const localpart  = from_email.split("@")[0] || "";
  const listUnsub  = getHeader(j,"List-Unsubscribe");
  const precedence = getHeader(j,"Precedence").toLowerCase();
  const autoSub    = getHeader(j,"Auto-Submitted").toLowerCase();
  const hay        = (subject+" "+bodyFull).toLowerCase();
  const subjLc     = subject.toLowerCase();

  let decision="UNKNOWN", reason="";

  if(TEAM.has(from_email)){ decision="TEAM"; reason="Sender on internal team list."; }
  else if(FORM_SENDERS.has(from_email)){ decision="FORM"; reason="Website form submission (separate Forms workflow)."; }
  else {
    const schedulerSender = domain==="calendly.com"
      || from_email==="user@example.com"
      || domain.endsWith("calendar.google.com")
      || domain==="zoom.us";
    const meetingSubject =
      /^(invitation:|updated invitation:|accepted:|declined:|tentatively accepted:|canceled event:|cancelled event:|new event:)/.test(subjLc)
      || /\bhas been scheduled\b/.test(hay)
      || /\bcalendly\b/.test(hay)
      || /(reschedule|meeting invitation|scheduled a meeting|booking confirmed|invite you to a meeting)/.test(hay);
    const meetingLink =
      /calendly\.com\//.test(hay) || /meet\.google\.com\//.test(hay)
      || /zoom\.us\/j\//.test(hay) || /teams\.microsoft\.com\/l\/meetup/.test(hay);

    if(schedulerSender||meetingSubject||meetingLink){ decision="MEETING"; reason="Calendar / scheduling signal."; }
    else {
      const otp =
        /\b(verification code|one[- ]?time (?:code|password)|otp|security code|login code|2fa|two[- ]?factor|confirm your email|reset your password)\b/.test(hay)
        || /\b\d{4,8}\b[^\n]{0,40}(code|verify|verification)/.test(hay);
      const bulkHeader = !!listUnsub || precedence==="bulk" || precedence==="list" || (autoSub && autoSub!=="no");
      const bulkSender = /^(no-?reply|do-?not-?reply|donotreply|noreply|mailer-daemon|bounce|bounces|notifications?|newsletter|marketing|mailer|postmaster)$/.test(localpart);
      if(otp){ decision="TRASH"; reason="Verification / OTP / transactional security email (not a keeper)."; }
      else if(bulkHeader||bulkSender){ decision="TRASH"; reason="Bulk / marketing / no-reply signal (List-Unsubscribe or bulk sender)."; }
    }
  }

  const llm_user =
    "FROM_NAME: "+from_name+"\n"+
    "FROM_EMAIL: "+from_email+"\n"+
    "SUBJECT: "+subject+"\n"+
    "BODY:\n"+body;

  out.push({
    json:{ id, threadId, from_email, from_name, subject, body, received_ms, decision, reason, llm_system:LLM_SYSTEM, llm_user },
    pairedItem:i
  });
}
return out;

// Defensive parse. FAIL SAFE: anything unreadable -> REVIEW (never TRASH).
const raw = $json;
let content = "";
if(raw && typeof raw==="object"){
  content = raw.content ?? (raw.message && raw.message.content) ?? raw.text ?? raw.output_text
         ?? (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content) ?? "";
  if(!content && Array.isArray(raw.output)){
    for(const o of raw.output){
      if(o && Array.isArray(o.content)){
        for(const c of o.content){ if(c && c.text){ content = c.text; break; } }
      }
    }
  }
}
let parsed = null;
if(!content && raw && (raw.category || raw.evidence)) parsed = raw; // node already returned parsed JSON
if(!parsed){
  try{
    const cleaned = String(content).replace(/^```(?:json)?/i,"").replace(/```$/i,"").trim();
    parsed = JSON.parse(cleaned);
  }catch(e){
    parsed = { category:"REVIEW", evidence:"", summary:"LLM output unparseable - routed to Review." };
  }
}
let cat = String(parsed.category || "REVIEW").toUpperCase();
if(!["LEAD","TRASH","REVIEW"].includes(cat)) cat = "REVIEW";

const src = $('Execute Pre-Classify Rules1').item.json;
return { json:{
  decision: cat,
  evidence: parsed.evidence || "",
  summary:  parsed.summary  || "",
  id: src.id, threadId: src.threadId,
  from_email: src.from_email, from_name: src.from_name,
  subject: src.subject, received_ms: src.received_ms
}};

// Compute WHEN a TRASH email should be deleted, per the rules:
//  - Fri / Sat / Sun received      -> next Monday 13:00
//  - Mon-Thu received AFTER 17:00  -> next day 13:00
//  - Mon-Thu received before 17:00 -> +2 hours
//  - Guard: never land on Fri/Sat/Sun -> push to next Monday 13:00
// Produces an ABSOLUTE instant (delete_at_iso) so the Wait node resumes exactly then.

const TZ = 'America/New_York'; // <-- CHANGE to your business timezone (e.g. 'Europe/London', 'America/Toronto', 'Asia/Makassar')
const DT = (typeof DateTime !== 'undefined') ? DateTime : $now.constructor;

function recvOf(j){
  if(j.received_ms){ const n=Number(j.received_ms); if(!isNaN(n)&&n>0) return DT.fromMillis(n,{zone:TZ}); }
  if(j.internalDate){ const n=Number(j.internalDate); if(!isNaN(n)&&n>0) return DT.fromMillis(n,{zone:TZ}); }
  if(j.date){ const d=new Date(j.date); if(!isNaN(d.getTime())) return DT.fromMillis(d.getTime(),{zone:TZ}); }
  return $now.setZone(TZ);
}
function nextMonday1pm(dt){
  let d=dt;
  while(d.weekday!==1) d=d.plus({days:1});
  return d.set({hour:13,minute:0,second:0,millisecond:0});
}

const out=[];
const items=$input.all();
for(let i=0;i<items.length;i++){
  const j=items[i].json;
  const recv=recvOf(j);
  const dow=recv.weekday, hour=recv.hour; // Mon=1 .. Sun=7
  let target;
  if(dow>=5){                 // Fri / Sat / Sun
    target=nextMonday1pm(recv);
  } else if(hour>=17){        // Mon-Thu after 5pm
    target=recv.plus({days:1}).set({hour:13,minute:0,second:0,millisecond:0});
  } else {                    // Mon-Thu before 5pm
    target=recv.plus({hours:2});
  }
  if(target.weekday>=5) target=nextMonday1pm(target); // never delete on Fri/Sat/Sun
  const nowZ=$now.setZone(TZ);
  if(target < nowZ) target=nowZ.plus({seconds:30});    // never schedule in the past

  out.push({
    json:{ ...j, delete_at_iso: target.toISO(), delete_at_human: target.toFormat("cccc, LLL d yyyy, h:mm a ZZZZ") },
    pairedItem:i
  });
}
return out;
